const launch=$('.launch-intro');
document.documentElement.classList.remove('booting');
function afterLaunch(){
 if(!launch.isConnected)return;
 launch.remove();
 $('.app').inert=false;$('.bottom-nav').inert=false;
 if(!state.settings.onboarded&&!storageProblem)startTour();
 window.MonoDeposits?.accrue();window.MonoNative?.pushWidget?.();
 // Уведомления: спрашиваем один раз при первом открытии, дальше узнаём текущий статус
 if(window.MonoNative){if(!state.settings.notifyAsked&&!storageProblem){const next=structuredClone(state);next.settings.notifyAsked=true;persist(next);setTimeout(()=>MonoNative.enableReminders(true),600);}else MonoNative.checkPermission?.();}
 window.MonoHomeCarousel?.reveal($('#homeReminders'));
}
if(reducedMotion())queueMicrotask(afterLaunch);
else{
 $('#homeReminders').classList.add('rem-waiting');setTimeout(()=>window.MonoHomeCarousel?.reveal($('#homeReminders')),1000);
 $('.app').inert=true;$('.bottom-nav').inert=true;
 const timeout=setTimeout(afterLaunch,1750);
 launch.addEventListener('animationend',event=>{
  if(event.target!==launch)return;
  clearTimeout(timeout);afterLaunch();
 });
}
if(storageProblem)notify(storageMessage);
window.MonoNative?.refreshReminders();

